import 'dart:convert';import 'dart:io';import 'package:licensebox/licensebox.dart';
Object? run(Map<String,dynamic> r){final product=r['product'] as String;final keys=Map<String,String>.from(r['keys']??{});
 switch(r['op']){case 'derive':return Client.deriveBinding(product,r['source'],r['raw_id']);case 'native':return Client.nativeBinding(product);case 'verify':return Client.verifyLease(r['token'],product,keys,(r['now'] as num).toDouble());}
 final c=Client(product:product,keys:keys,version:'conformance',server:r['server'],caBundle:r['ca_bundle'],directory:r['directory'],hooks:Hooks(clock:()=>(r['now'] as num).toDouble(),machineBinding:()=>r['binding'],onSignIn:(u,c){}));
 try{switch(r['op']){case 'heartbeat':return c.heartbeat(r['module']??'core');case 'heartbeat-repeat':c.heartbeat(r['module']??'core');return c.heartbeat(r['module']??'core');case 'heartbeat-after-require':c.requireModule(r['module']??'core');return c.heartbeat(r['module']??'core');case 'lease':return c.lease();case 'status':return c.status();case 'sign_in':return c.signIn(timeout:3);case 'require':return c.requireModule(r['module']??'core');case 'repeat':c.requireModule('core');return c.requireModule('core');case 'logout':c.logout();return null;case 'modules':return c.modules();case 'requests':return c.requests();case 'request':return c.requestAccess(['export'],note:'café – test');case 'access-link':return c.accessLink();case 'record':c.record('export',success:true,elapsed:.125);c.record('export',success:false,elapsed:.025);return null;default:throw StateError('unknown operation');}}finally{c.close();}
}
Future<void> main()async{final r=jsonDecode(await stdin.transform(utf8.decoder).join()) as Map<String,dynamic>;try{stdout.writeln(jsonEncode({'ok':true,'value':run(r)}));}on LicenseboxException catch(e){stdout.writeln(jsonEncode({'ok':false,'error':e.code}));}}
